+const { useState, useMemo, useRef } = React;
+
+const QUESTIONS = [
+  {
+    id: "q1",
+    prompt: "Which of the following are statically typed languages?",
+    helpText: "Select all that apply. Statically typed means types are checked at compile time.",
+    options: [
+      { id: "q1a", label: "TypeScript", correct: true },
+      { id: "q1b", label: "Python", correct: false },
+      { id: "q1c", label: "Rust", correct: true },
+      { id: "q1d", label: "JavaScript", correct: false },
+    ],
+  },
+  {
+    id: "q2",
+    prompt: "Which languages run primarily on the JVM?",
+    options: [
+      { id: "q2a", label: "Kotlin", correct: true },
+      { id: "q2b", label: "Scala", correct: true },
+      { id: "q2c", label: "Go", correct: false },
+      { id: "q2d", label: "Swift", correct: false },
+    ],
+  },
+  {
+    id: "q3",
+    prompt: "Which of these are functional programming languages?",
+    options: [
+      { id: "q3a", label: "Haskell", correct: true },
+      { id: "q3b", label: "C", correct: false },
+      { id: "q3c", label: "Elixir", correct: true },
+      { id: "q3d", label: "COBOL", correct: false },
+    ],
+  },
+];
+
+function CheckboxOption({ option, name, checked, onChange }) {
+  return (
+    <label className="option" htmlFor={option.id}>
+      <input
+        id={option.id}
+        type="checkbox"
+        name={name}
+        value={option.id}
+        checked={checked}
+        onChange={(e) => onChange(option.id, e.target.checked)}
+      />
+      <span className="label-text">{option.label}</span>
+    </label>
+  );
+}
+
+function Question({ index, question, selected, onToggle }) {
+  const helpId = `${question.id}-help`;
+  const describedBy = question.helpText ? helpId : undefined;
+
+  return (
+    <div className="form-field">
+      <fieldset aria-describedby={describedBy}>
+        <legend>
+          <span className="q-number">Question {index + 1}.</span>
+          {question.prompt}
+        </legend>
+        {question.helpText && (
+          <p id={helpId} className="help-text">{question.helpText}</p>
+        )}
+        <div className="options">
+          {question.options.map((opt) => (
+            <CheckboxOption
+              key={opt.id}
+              option={opt}
+              name={question.id}
+              checked={selected.includes(opt.id)}
+              onChange={(id, isChecked) => onToggle(question.id, id, isChecked)}
+            />
+          ))}
+        </div>
+      </fieldset>
+    </div>
+  );
+}
+
+function Results({ results }) {
+  const liveRef = useRef(null);
+  return (
+    <section
+      className="results"
+      aria-labelledby="results-heading"
+      aria-live="polite"
+      ref={liveRef}
+    >
+      <h2 id="results-heading">Results</h2>
+      <p className="score">
+        You scored {results.score} out of {results.total}.
+      </p>
+      <ul>
+        {results.perQuestion.map((r, i) => (
+          <li key={r.id} className={r.correct ? "correct" : "incorrect"}>
+            Question {i + 1}: {r.correct ? "Correct" : "Incorrect"}
+          </li>
+        ))}
+      </ul>
+    </section>
+  );
+}
+
+function Quiz() {
+  const [answers, setAnswers] = useState(() =>
+    Object.fromEntries(QUESTIONS.map((q) => [q.id, []]))
+  );
+  const [results, setResults] = useState(null);
+
+  const handleToggle = (questionId, optionId, isChecked) => {
+    setAnswers((prev) => {
+      const current = prev[questionId] || [];
+      const next = isChecked
+        ? [...current, optionId]
+        : current.filter((id) => id !== optionId);
+      return { ...prev, [questionId]: next };
+    });
+  };
+
+  const handleSubmit = (e) => {
+    e.preventDefault();
+    const perQuestion = QUESTIONS.map((q) => {
+      const selected = new Set(answers[q.id] || []);
+      const correctSet = new Set(
+        q.options.filter((o) => o.correct).map((o) => o.id)
+      );
+      const isCorrect =
+        selected.size === correctSet.size &&
+        [...selected].every((id) => correctSet.has(id));
+      return { id: q.id, correct: isCorrect };
+    });
+    const score = perQuestion.filter((r) => r.correct).length;
+    setResults({ score, total: QUESTIONS.length, perQuestion });
+  };
+
+  return (
+    <form className="quiz" onSubmit={handleSubmit} noValidate>
+      {QUESTIONS.map((q, i) => (
+        <Question
+          key={q.id}
+          index={i}
+          question={q}
+          selected={answers[q.id]}
+          onToggle={handleToggle}
+        />
+      ))}
+      <div className="actions">
+        <button type="submit" className="submit">Submit answers</button>
+      </div>
+      {results && <Results results={results} />}
+    </form>
+  );
+}
+
+function App() {
+  return (
+    <>
+      <header className="page-header">
+        <h1>Computer Languages Quiz</h1>
+        <p>Three quick questions. Each one may have more than one correct answer.</p>
+      </header>
+      <Quiz />
+    </>
+  );
+}
+
+const root = ReactDOM.createRoot(document.getElementById("root"));
+root.render(<App />);
+
